 555→  /** Deactivate the user's account permanently
 556→   * Warning: This is irreversible and will delete all user data */
 557→  public static deactivateAccount = async (password: string) => {
 558→    if (!this.instance) throw new Error("Client not initialized");
 559→
 560→    try {
 561→      // First request with undefined auth_data (will always fail per UIA spec)
 562→      try {
 563→        await this.instance.deactivateAccount(undefined, true);
 564→      } catch {
 565→        // Expected to fail
 566→      }
 567→
 568→      console.log(this.instance.userId(), "userId");
 569→      const userId = this.instance.userId();
 570→      if (!userId) throw new Error("User ID not found");
 571→
 572→      const authData = new AuthData.Password({
 573→        passwordDetails: AuthDataPasswordDetails.create({
 574→          identifier: userId,
 575→          password,
 576→        }),
 577→      });
 578→
 579→      // Step 4: Second request with auth data
 580→      await this.instance.deactivateAccount(authData, true);
 581→
 582→      // After successful deactivation, clean up local data
 583→      await this.logout();
 584→    } catch (error) {
 585→      console.error("Failed to deactivate account:", error);
 586→      throw error;
 587→    }
 588→  };
