 592→    const room = this.instance.getRoom(roomId);
 593→    if (!room) throw new Error("Room not found");
 594→    const timeline = await room.timeline();
 595→    if (!timeline) throw new Error("Timeline not found");
 596→
 597→    // Create message content from markdown (supports plain text too)
 598→    const messageContent = messageEventContentFromMarkdown(message);
 599→
 600→    // Send the message and return the send handle
 601→    await timeline.send(messageContent);
 602→  };
