 900→  /** Check if a direct room exists with a user */
 901→  public static getExistingDirectRoom = async (
 902→    userId: string,
 903→  ): Promise<string | null> => {
 904→    if (!this.instance) throw new Error("Client not initialized");
 905→
 906→    try {
 907→      const rooms = this.instance.rooms();
 908→      for (const room of rooms) {
 909→        const roomInfo = await room.roomInfo();
 910→        if (roomInfo?.isDirect) {
 911→          const members = await room.members();
 912→          const memberList = members.nextChunk(100000) ?? [];
 913→          const hasUser = memberList.some((member) => member.userId === userId);
 914→          if (hasUser) return room.id();
 915→        }
 916→      }
 917→      return null;
 918→    } catch (error) {
 919→      console.error("Failed to check for existing direct room:", error);
 920→      return null;
 921→    }
 922→  };
