 1→import { useAtomValue, useSetAtom } from "jotai";
 2→import type { FC, PropsWithChildren } from "react";
 3→import { useEffect, useRef } from "react";
 4→import { RecorderPlayerAtoms } from "../jotai";
 5→
 6→export const AudioPlaybackProvider: FC<PropsWithChildren> = ({ children }) => {
 7→  const isListenersSetup = useRef(false);
 8→  const sound = useAtomValue(RecorderPlayerAtoms.soundInstanceAtom);
 9→  const setCurrentMs = useSetAtom(RecorderPlayerAtoms.setCurrentMsAtom);
10→  const resetPlayback = useSetAtom(RecorderPlayerAtoms.resetPlaybackAtom);
11→
12→  useEffect(() => {
13→    if (isListenersSetup.current) return;
14→    isListenersSetup.current = true;
15→
16→    sound.addPlayBackListener((e) => {
17→      setCurrentMs(e.currentPosition);
18→    });
19→
20→    sound.addPlaybackEndListener(() => {
21→      resetPlayback();
22→    });
23→
24→    // Cleanup on unmount
25→    return () => {
26→      sound.removePlayBackListener();
27→      sound.removePlaybackEndListener();
28→      isListenersSetup.current = false;
29→    };
30→  }, [sound, setCurrentMs, resetPlayback]);
31→
32→  return <>{children}</>;
33→};
