import { atom } from "jotai";

interface AudioPlaybackState {
  currentTrack: AudioTrack | null;
  isPlaying: boolean;
  currentMs: number;
}

const eventId = atom<string | null>(null);
const soundInstanceAtom = atom(() => createSound());
const audioPlaybackAtom = atom<AudioPlaybackState>({...});

// Write atoms that update other atoms
const loadTrackAtom = atom(null, (get, set, track: AudioTrack) => {
  const currentState = get(audioPlaybackAtom);
  if (currentState.currentTrack?.trackId !== track.trackId) {
    set(audioPlaybackAtom, { currentTrack: track, isPlaying: false, currentMs: 0 });
  }
});

const setIsPlayingAtom = atom(null, (get, set, isPlaying: boolean) => {
  const currentState = get(audioPlaybackAtom);
  set(audioPlaybackAtom, { ...currentState, isPlaying });
});

const resetPlaybackAtom = atom(null, (get, set) => {
  const currentState = get(audioPlaybackAtom);
  set(audioPlaybackAtom, { ...currentState, isPlaying: false, currentMs: 0 });
});
```

**Patterns Identified:**
1. **Simple atoms:** `atom<Type>(initialValue)`
2. **Nullable atoms:** `atom<Type | null>(null)`
3. **Array atoms:** `atom<Type[]>([])`
4. **Persistent atoms:** `atomWithStorage<Type>(key, defaultValue, adapter)`
5. **Write-only atoms:** `atom(null, (get, set, payload) => {...})` - accepts write actions
6. **Factory atoms:** `atom(() => createInstance())` - creates new instances

