```typescript
// Get user's power level in a room
public static getUserPowerLevel = async (roomId: string, userId?: string) => {
  if (!this.instance) return null;
  const room = this.instance.getRoom(roomId);
  if (!room) return null;
  const member = await room.member(userId ?? this.instance.userId());
  return Number(
    member.powerLevel.tag === PowerLevel_Tags.Value
      ? member.powerLevel.inner.value
      : 0,
  );
};

// Remove user from room (kick)
public static removeUserFromRoom = async (
  roomId: string,
  userId: string,
  reason?: string,
) => {
  if (!this.instance) return;
  const room = this.instance.getRoom(roomId);
  if (!room) return;
  await room.kickUser(userId, reason);
  await this.refreshRoomList();
};

// Ban user from room
public static banUserFromRoom = async (
  roomId: string,
  userId: string,
  reason?: string,
) => {
  if (!this.instance) return;
  const room = this.instance.getRoom(roomId);
  if (!room) return;
  await room.banUser(userId, reason);
  await this.refreshRoomList();
};

// Unban user from room
public static unbanUserFromRoom = async (
  roomId: string,
  userId: string,
  reason?: string,
) => {
  if (!this.instance) return;
  const room = this.instance.getRoom(roomId);
  if (!room) return;
  await room.unbanUser(userId, reason);
  await this.refreshRoomList();
};

// Get room information
public static getRoomInfo = (roomId: string) => {
  if (!this.instance) throw new Error("Client not initialized");
  const room = this.instance.getRoom(roomId);
  if (!room) return null;
  return room;
};

// Refresh room list and update atoms
public static refreshRoomList = async () => {
  if (!this.instance) return;
  try {
    const roomsArray = this.getRooms();
    const sortedRooms = await Promise.all(
      roomsArray.map(async (room) => ({
        room,
        timestamp: (await room.latestEvent())?.timestamp || 0,
      })),
    );
    const filteredAndSortedRooms = sortedRooms
      .filter(({ room }) => {
        const membership = room.membership();
        return (
          membership !== Membership.Banned &&
          membership !== Membership.Left &&
          membership !== Membership.Knocked
        );
      })
      .sort((a, b) => {
        const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
        const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
        if (aInvited !== bInvited) return bInvited - aInvited;
        return Number(b.timestamp) - Number(a.timestamp);
      });

    MatrixJotaiStore.set(
      MatrixAtoms.roomList,
      filteredAndSortedRooms.map(({ room }) => room),
    );
  } catch (error) {
    console.error("Failed to refresh room list:", error);
  }
};
```

